class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 2:
            return n

        # dp[i] will store the length of the longest subsequence ending at index i
        dp = [1] * n

        # To store the maximum length found
        max_length = 1

        # Iterate through each pair of indices to find valid subsequences
        for i in range(n):
            for j in range(i):
                # Calculate the absolute difference
                diff1 = abs(nums[i] - nums[j])

                # Check if we can form a valid subsequence
                if j > 0:
                    diff2 = abs(nums[j] - nums[j-1])
                    if diff1 <= diff2:
                        dp[i] = max(dp[i], dp[j] + 1)
                else:
                    dp[i] = max(dp[i], dp[j] + 1)

            max_length = max(max_length, dp[i])

        return max_length
