from typing import List
from itertools import combinations

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)
        max_score = 0
        best_indices = []

        # Check all combinations of up to 4 intervals
        for k in range(1, 5):
            for indices in combinations(range(n), k):
                total_weight = sum(intervals[i][2] for i in indices)
                if self.are_non_overlapping(indices, intervals):
                    if (total_weight > max_score) or (total_weight == max_score and list(indices) < best_indices):
                        max_score = total_weight
                        best_indices = list(indices)

        return sorted(best_indices)

    def are_non_overlapping(self, indices: List[int], intervals: List[List[int]]) -> bool:
        # Check if the intervals at the given indices are non-overlapping
        sorted_intervals = sorted((intervals[i][0], intervals[i][1]) for i in indices)
        end = -1
        for start, finish in sorted_intervals:
            if start <= end:  # Overlapping condition
                return False
            end = finish
        return True
